BEGIN;
ALTER TABLE iam.capabilities ADD COLUMN parent_code text;
ALTER TABLE iam.capabilities ADD COLUMN ui_metadata jsonb NOT NULL DEFAULT '{}'::jsonb;
ON CONFLICT(code) DO UPDATE SET name=EXCLUDED.name,description=EXCLUDED.description,module=EXCLUDED.module,parent_code=EXCLUDED.parent_code,ui_metadata=EXCLUDED.ui_metadata;
GRANT SELECT ON iam.capabilities TO fab_control_runtime;

CREATE FUNCTION platform.current_permission_policy() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER
SET search_path=pg_catalog,platform AS $$
 SELECT jsonb_build_object('personalizavel',COALESCE((plan.limits->'permissions'->>'personalizavel')::boolean,true),
 'permissoes',plan.limits->'permissions'->'permissoes','plano',plan.code,
 'recursos',CASE WHEN subscription.id IS NULL THEN NULL ELSE COALESCE((SELECT jsonb_agg(feature.code)
 FROM platform.feature_catalog feature WHERE feature.status='ACTIVE' AND COALESCE(
 (subscription.overrides->'features'->>feature.code)::boolean,
 (SELECT enabled FROM platform.commercial_plan_features pf WHERE pf.commercial_plan_id=plan.id AND pf.feature_id=feature.id),false)),'[]'::jsonb) END)
 FROM (SELECT platform.current_tenant_id() AS id) tenant
 LEFT JOIN LATERAL(SELECT * FROM platform.tenant_subscriptions WHERE tenant_id=tenant.id ORDER BY starts_at DESC,created_at DESC,id DESC LIMIT 1) subscription ON true
 LEFT JOIN platform.commercial_plans plan ON plan.id=subscription.commercial_plan_id
$$;
ALTER FUNCTION platform.current_permission_policy() OWNER TO vorqix_platform_reader;
REVOKE ALL ON FUNCTION platform.current_permission_policy() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION platform.current_permission_policy() TO fab_control_runtime;

CREATE FUNCTION platform.read_console_permission_policy(p_plan_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER
SET search_path=pg_catalog,platform AS $$
 SELECT jsonb_build_object('personalizavel',COALESCE((limits->'permissions'->>'personalizavel')::boolean,true),'permissoes',limits->'permissions'->'permissoes') FROM platform.commercial_plans WHERE id=p_plan_id
$$;
ALTER FUNCTION platform.read_console_permission_policy(uuid) OWNER TO vorqix_platform_reader;
REVOKE ALL ON FUNCTION platform.read_console_permission_policy(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION platform.read_console_permission_policy(uuid) TO fab_control_runtime;

CREATE FUNCTION platform.save_console_permission_policy(p_operator uuid,p_plan uuid,p_customizable boolean,p_codes text[],p_request text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,platform,iam AS $$
DECLARE before_policy jsonb;
BEGIN
 IF p_codes IS NOT NULL AND EXISTS(SELECT 1 FROM unnest(p_codes) code WHERE NOT EXISTS(SELECT 1 FROM iam.capabilities c WHERE c.code=code AND c.status='ACTIVE')) THEN
 RAISE EXCEPTION 'Permissão desconhecida.' USING ERRCODE='22023'; END IF;
 SELECT limits->'permissions' INTO before_policy FROM platform.commercial_plans WHERE id=p_plan FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Plano não encontrado.' USING ERRCODE='P0002'; END IF;
 UPDATE platform.commercial_plans SET limits=jsonb_set(limits,'{permissions}',jsonb_build_object('personalizavel',p_customizable,'permissoes',to_jsonb(p_codes))),version=version+1 WHERE id=p_plan;
 VALUES(p_operator,'PLATFORM_PLAN_PERMISSIONS_UPDATED','COMMERCIAL_PLAN',p_plan::text,p_request,COALESCE(before_policy,'{}'::jsonb),jsonb_build_object('personalizavel',p_customizable,'permissoes',to_jsonb(p_codes)));
END $$;
GRANT SELECT ON iam.capabilities TO vorqix_platform_support_writer;
ALTER FUNCTION platform.save_console_permission_policy(uuid,uuid,boolean,text[],text) OWNER TO vorqix_platform_support_writer;
REVOKE ALL ON FUNCTION platform.save_console_permission_policy(uuid,uuid,boolean,text[],text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION platform.save_console_permission_policy(uuid,uuid,boolean,text[],text) TO fab_control_runtime;

ON CONFLICT(code) DO NOTHING;
 SELECT plan.id,feature.id,true FROM platform.commercial_plans plan CROSS JOIN platform.feature_catalog feature
 WHERE plan.code IN('BASICO','INICIAL','EMPRESARIAL') AND plan.status='DRAFT' AND feature.status='ACTIVE'
 AND (plan.code='EMPRESARIAL' OR feature.code IN('CADASTROS','ORDENS_SERVICO','CHECKLISTS') OR plan.code='INICIAL' AND feature.code IN('GESTAO_TECNICA','INDICADORES'))
ON CONFLICT(commercial_plan_id,feature_id) DO NOTHING;
COMMIT;
